// evidence.fixture.ts — generated by `harness_evidence --action=fixture`.
// OpenHarness walkthrough producer (ADR 0007): turn Playwright runs into
// `steps.json` fragments that `harness_evidence --action=attach --fragment`
// folds into a `kind: "walkthrough"` evidence bundle.
//
// Usage:
//   1. import { test, expect } from "./evidence.fixture";   // instead of @playwright/test
//   2. EVIDENCE_RUN_DIR=/tmp/walkthrough npx playwright test e2e/wave.spec.ts
//   3. python -m openharness run harness_evidence --action=new --repo=<repo> \
//        --feature=<feature> --wave=<n> --kind=walkthrough
//   4. python -m openharness run harness_evidence --action=attach \
//        --bundle=<walkthrough bundle> --fragment=$EVIDENCE_RUN_DIR/steps-<spec>.json
//
// Covers web and mobile-web (device emulation in playwright.config).
// Electron desktop and native mobile apps are different producers emitting
// the same fragment — adapt the launch, keep the steps.json shape.

import { test as base } from "@playwright/test";
import { mkdirSync, writeFileSync } from "node:fs";
import { basename, join } from "node:path";

const RUN_DIR = process.env.EVIDENCE_RUN_DIR || "./evidence-run";
const SHOTS = join(RUN_DIR, "shots");

type Artifact = { path: string; caption?: string; role?: string };
type Step = {
  id: string; title: string; kind: "browser"; status: "pass" | "fail";
  started_at: string; duration_ms: number; artifacts: Artifact[];
};

const byFile = new Map<string, Step[]>();
const counters = new Map<string, number>();

function slug(s: string): string {
  return s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 40) || "step";
}

async function shot(
  page: import("@playwright/test").Page,
  fileKey: string,
  n: number,
  title: string,
  failed: boolean,
): Promise<Artifact[]> {
  mkdirSync(SHOTS, { recursive: true });
  const arts: Artifact[] = [];
  const png = join(SHOTS, `${fileKey}-s${n}-${slug(title)}.png`);
  await page.screenshot({ path: png }).catch(() => {});
  arts.push({ path: png, caption: `${failed ? "FAILED: " : ""}${title}` });
  if (failed) {
    try {
      const video = page.video();
      if (video) {
        const webm = join(SHOTS, `${fileKey}-s${n}-${slug(title)}.webm`);
        await video.saveAs(webm).catch(() => {});
        arts.push({ path: webm, role: "video", caption: `recording — ${title}` });
      }
    } catch { /* video not enabled for this context */ }
  }
  return arts.filter((a) => a.path);
}

export const test = base.extend({
  evidence: async ({ page }, use, testInfo) => {
    const fileKey = slug(basename(testInfo.file).replace(/\.spec\.[tj]s$/, ""));
    await use({
      step: async (title: string, fn: () => Promise<void>) => {
        const n = (counters.get(testInfo.file) ?? 0) + 1;
        counters.set(testInfo.file, n);
        const started = new Date().toISOString();
        const t0 = Date.now();
        let status: "pass" | "fail" = "pass";
        try {
          await fn();
        } catch (err) {
          status = "fail";
          const arts = await shot(page, fileKey, n, title, true);
          const arr = byFile.get(testInfo.file) ?? [];
          arr.push({
            id: `${fileKey}-s${n}`, title, kind: "browser", status,
            started_at: started, duration_ms: Date.now() - t0, artifacts: arts,
          });
          byFile.set(testInfo.file, arr);
          throw err;
        }
        const arts = await shot(page, fileKey, n, title, false);
        const arr = byFile.get(testInfo.file) ?? [];
        arr.push({
          id: `${fileKey}-s${n}`, title, kind: "browser", status,
          started_at: started, duration_ms: Date.now() - t0, artifacts: arts,
        });
        byFile.set(testInfo.file, arr);
      },
    });
  },
  _flushEvidence: [
    async ({}, use, testInfo) => {
      await use();
      mkdirSync(RUN_DIR, { recursive: true });
      const fileKey = slug(basename(testInfo.file).replace(/\.spec\.[tj]s$/, ""));
      writeFileSync(
        join(RUN_DIR, `steps-${fileKey}.json`),
        JSON.stringify(byFile.get(testInfo.file) ?? [], null, 2) + "\n",
      );
    },
    { auto: true },
  ],
});

export { expect } from "@playwright/test";
